import{_ as n,o as e,c,a5 as t}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"DA-949 / E50-08 — Danh bạ đối tác Agency","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/partner-directory/spec.md","filePath":"feature/media-package-campaign/partner-directory/spec.md"}'),i={name:"feature/media-package-campaign/partner-directory/spec.md"};function o(h,a,r,d,l,s){return e(),c("div",null,[...a[0]||(a[0]=[t('<h1 id="da-949-e50-08-—-danh-ba-đoi-tac-agency" tabindex="-1">DA-949 / E50-08 — Danh bạ đối tác Agency <a class="header-anchor" href="#da-949-e50-08-—-danh-ba-đoi-tac-agency" aria-label="Permalink to &quot;DA-949 / E50-08 — Danh bạ đối tác Agency&quot;">​</a></h1><p>Ngày: 2026-10-13. Thiết kế trước code; Q2 đã chốt: chỉ Agency Owner quản lý danh bạ.</p><h2 id="muc-đich-va-pham-vi" tabindex="-1">Mục đích và phạm vi <a class="header-anchor" href="#muc-đich-va-pham-vi" aria-label="Permalink to &quot;Mục đích và phạm vi&quot;">​</a></h2><p>Agency lưu đối tác báo/banner/TV/khác để sử dụng trong nhiều Campaign. Danh bạ lưu thông tin đối tác; campaign_collaborators lưu trạng thái hợp tác riêng từng Campaign. Không gọi bên thứ ba, booking, thanh toán, AI recommendation hoặc tự publish.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li><p>Confirmed 2026-10-14: optional phone supports Vietnam and international formats (7–15 digits; optional leading + and formatting spaces/hyphens/parentheses). Validate phone/email/HTTP(S) website on UI and server, preserve unknown contact keys. Format validation does not prove ownership or reachability. See ../request-completion-validation/spec.md.</p></li><li><p>CRUD luôn scope theo Agency: tên, loại NEWSPAPER/BANNER/TV/OTHER, contactInfo, notes và audit fields; không chuyển đối tác sang Agency khác qua update.</p></li><li><p>Thêm <code>isActive</code> (mặc định true cho dữ liệu cũ). Danh bạ quản lý thấy cả active/inactive; lựa chọn gán mới chỉ thấy active.</p></li><li><p>Đối tác chưa từng được Campaign sử dụng: được xóa hẳn. Đối tác đã được sử dụng: chỉ chuyển inactive; xóa trả 409, không xóa/cascade liên kết hay thông tin lịch sử.</p></li><li><p>Liên kết đã tồn tại vẫn hiển thị đối tác inactive và cho cập nhật hợp tác theo quyền DA-950. Gán lặp lại một liên kết tồn tại không tạo mới hoặc reset trạng thái.</p></li><li><p>Inactive không được tạo liên kết mới, kể cả qua API legacy. Không làm tính năng kích hoạt lại trong đợt này nếu chưa có xác nhận BA.</p></li><li><p>Delete/deactivate và assign đồng thời được xử lý nguyên tử, không tạo tham chiếu mồ côi hoặc link mới tới đối tác đã inactive.</p></li><li><p>Chỉ Agency Owner tạo/sửa/xóa/ngừng sử dụng và xem danh bạ quản lý. Manager/Creator chỉ đọc/chọn active và gán theo Workspace scope/quyền DA-950; Client đọc đối tác đã liên kết, không quản lý danh bạ. Không suy ra quyền quản lý từ Agency MEMBER.</p></li></ul><h2 id="api-du-kien" tabindex="-1">API dự kiến <a class="header-anchor" href="#api-du-kien" aria-label="Permalink to &quot;API dự kiến&quot;">​</a></h2><p><code>/api/v1/agencies/{agencyId}/collaborators</code>: GET phân trang/lọc, POST tạo; <code>/{collaboratorId}</code>: GET, PATCH sửa và DELETE; <code>/{collaboratorId}/deactivate</code>: POST. DTO write dùng version hoặc expectedUpdatedAt chống ghi đè. Đây là contract dự kiến cần đối chiếu OpenAPI/consumer trước code, không phá endpoint legacy <code>/api/v1/collaborators</code>.</p><h2 id="ui" tabindex="-1">UI <a class="header-anchor" href="#ui" aria-label="Permalink to &quot;UI&quot;">​</a></h2><p>Danh bạ cấp Agency tách khỏi trang đối tác Campaign, route dự kiến <code>/agency/:agencyId/collaborators</code>, sidebar chỉ Owner. Có trạng thái loading/empty/error, tìm kiếm/phân trang, form tạo/sửa, xác nhận xóa/ngừng sử dụng và badge inactive. Namespace mới <code>collaborators</code>: <code>title</code>, <code>fields.*</code>, <code>status.active</code>, <code>status.inactive</code>, <code>actions.*</code>, <code>confirm.*</code>, <code>errors.*</code>, <code>empty</code>, <code>loading</code>; thêm song song locale vi/en. Semantic theme tokens, keyboard/focus, mobile và light/dark bắt buộc; không thay menu module khác.</p><h2 id="lich-su-su-dung" tabindex="-1">Lịch sử sử dụng <a class="header-anchor" href="#lich-su-su-dung" aria-label="Permalink to &quot;Lịch sử sử dụng&quot;">​</a></h2><p>Xác nhận 2026-10-13: dữ liệu cũ chưa xác minh lịch sử <strong>khóa xóa</strong>, vẫn sửa/ngừng sử dụng được. Thêm <code>usageHistoryVerified</code> (legacy=false; API create mới=true). Không cung cấp API tự xác nhận lại lịch sử hoặc reactivate trong đợt này. Chỉ xóa khi flag=true, firstUsedAt=null và không có link. UI hiển thị lý do khóa.</p><p>Schema hiện tại có FK ON DELETE RESTRICT nhưng chưa có dấu vết &quot;đã từng dùng&quot; nếu Campaign/link sau này bị xóa. Cần lưu marker sử dụng bền vững (đề xuất <code>firstUsedAt</code>), backfill từ liên kết đang có, và cập nhật atomically khi gán lần đầu. Không đoán được lịch sử đã mất; inventory và báo team trước migration. Đổi tên/liên hệ không tạo snapshot lịch sử mới trong scope này.</p>',13)])])}const u=n(i,[["render",o]]);export{p as __pageData,u as default};
